#!/usr/bin/env python3
"""
EnviroMap-KG / Standards-Aware Multi-Agent Semantic Interoperability
Self-Extracting Server Installer for: cse-dept@cse-dept-HP (192.168.0.21)

This script recreates the complete project directory structure and all 40+ files
directly on the server, installs dependencies, and prepares PostgreSQL discovery.
"""

import os
import sys
import base64
import gzip
import io
import tarfile
import subprocess

TARGET_DIR = os.path.abspath(os.path.expanduser("~/semantic-interoperability-kg"))
PAYLOAD = ""

def main():
    print("=" * 70)
    print("EnviroMap-KG — Server Installation on cse-dept@cse-dept-HP")
    print(f"Target Directory: {TARGET_DIR}")
    print("=" * 70)

    # 1. Create target directory
    os.makedirs(TARGET_DIR, exist_ok=True)

    # 2. Extract files
    print("\n[1/4] Extracting project files...")
    tar_bytes = base64.b64decode(PAYLOAD)
    tar_buffer = io.BytesIO(tar_bytes)
    with tarfile.open(fileobj=tar_buffer, mode="r:gz") as tar:
        tar.extractall(path=TARGET_DIR)
    print(f"  [OK] Successfully created project files in {TARGET_DIR}")

    # 3. Create virtual environment
    print("\n[2/4] Setting up Python virtual environment...")
    venv_dir = os.path.join(TARGET_DIR, "venv")
    if not os.path.exists(venv_dir):
        subprocess.run([sys.executable, "-m", "venv", venv_dir], check=True)
        print("  [OK] Virtual environment created.")
    else:
        print("  [OK] Existing virtual environment found.")

    pip_path = os.path.join(venv_dir, "bin", "pip")
    py_path = os.path.join(venv_dir, "bin", "python")

    # 4. Install dependencies
    print("\n[3/4] Installing dependencies (rdflib, psycopg2-binary, rapidfuzz, pyyaml, fastapi, uvicorn)...")
    req_file = os.path.join(TARGET_DIR, "requirements.txt")
    subprocess.run([pip_path, "install", "--upgrade", "pip"], check=False)
    subprocess.run([pip_path, "install", "-r", req_file], check=True)
    print("  [OK] Dependencies installed successfully.")

    # 5. Run test discovery
    print("\n[4/4] Testing database discovery...")
    disc_script = os.path.join(TARGET_DIR, "scripts", "discover_database.py")
    subprocess.run([py_path, disc_script])

    print("\n" + "=" * 70)
    print("Installation Complete!")
    print(f"Project location: {TARGET_DIR}")
    print("\nNext commands to run:")
    print(f"  cd {TARGET_DIR}")
    print("  source venv/bin/activate")
    print("  python scripts/run_pipeline.py")
    print("=" * 70)

if __name__ == "__main__":
    main()
